import{_ as a,a0 as l,w as r,s as d,ao as s,I as i,x as p,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"12个进程管理命令介绍 | LCTT x X-CMD","titleTemplate":false,"description":"12个进程管理命令介绍 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"12个进程管理命令介绍 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"12个进程管理命令介绍 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150326 A Peep into Process Management Commands in Linux","title":"12个进程管理命令介绍","tag":"201506","desc":""},"relativePath":"201506/20150326 A Peep into Process Management Commands in Linux.md","filePath":"[post].md"}'),c={name:"201506/20150326 A Peep into Process Management Commands in Linux.md"};function m(g,e,h,u,x,b){const t=l("Link");return r(),d("div",null,[e[13]||(e[13]=s(`<h1 id="_12个进程管理命令介绍" tabindex="-1">12个进程管理命令介绍 <a class="header-anchor" href="#_12个进程管理命令介绍" aria-label="Permalink to “12个进程管理命令介绍”">​</a></h1><p>执行中的程序在称作进程。当程序以可执行文件存放在存储中，并且运行的时候，每个进程会被动态得分配系统资源、内存、安全属性和与之相关的状态。可以有多个进程关联到同一个程序，并同时执行不会互相干扰。操作系统会有效地管理和追踪所有运行着的进程。</p><p>为了管理这些进程，用户应该能够：</p><ul><li>查看所有运行中的进程</li><li>查看进程消耗资源</li><li>定位个别进程并且对其执行指定操作</li><li>改变进程的优先级</li><li>杀死指定进程</li><li>限制进程可用的系统资源等</li></ul><p>Linux提供了许多命令来让用户来高效掌控上述的操作。接下来，一个一个的来讲解下。</p><h3 id="_1-ps" tabindex="-1">1. ps <a class="header-anchor" href="#_1-ps" aria-label="Permalink to “1. ps”">​</a></h3><p>&#39;ps&#39;是Linux 中最基础的浏览系统中的进程的命令。能列出系统中运行的进程，包括进程号、命令、CPU使用量、内存使用量等。下述选项可以得到更多有用的消息。</p><pre><code>ps -a - 列出所有运行中/激活进程
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/ps-a2.png" alt="Output of &quot;ps -a&quot; command"></p><pre><code>ps -ef |grep - 列出需要进程
ps -aux - 显示进程信息，包括无终端的（x）和针对用户（u）的进程：如USER, PID, %CPU, %MEM等
</code></pre><h3 id="_2-pstree" tabindex="-1">2. pstree <a class="header-anchor" href="#_2-pstree" aria-label="Permalink to “2. pstree”">​</a></h3><p>linux中，每一个进程都是由其父进程创建的。此命令以可视化方式显示进程，通过显示进程的树状图来展示进程间关系。如果指定了pid了，那么树的根是该pid，不然将会是init（pid： 1）。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/pstree.png" alt="pstree"></p><h3 id="_3-top" tabindex="-1">3. top <a class="header-anchor" href="#_3-top" aria-label="Permalink to “3. top”">​</a></h3><p>‘top’是一个更加有用的命令，可以监视系统中不同的进程所使用的资源。它提供实时的系统状态信息。显示进程的数据包括 PID、进程属主、优先级、%CPU、%memory等。可以使用这些显示指示出资源使用量。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/top.png" alt="top"></p><h3 id="_4-htop" tabindex="-1">4. htop <a class="header-anchor" href="#_4-htop" aria-label="Permalink to “4. htop”">​</a></h3><p>htop与top很类似，但是htop是交互式的文本模式的进程查看器。它通过文字图形化地显示每一个进程的CPU和内存使用量、swap使用量。使用上下光标键选择进程，F7和F8改变优先级，F9杀死进程。Htop不是系统默认安装的，所以需要额外安装。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/htop1.png" alt="htop output"></p><h3 id="_5-nice" tabindex="-1">5. nice <a class="header-anchor" href="#_5-nice" aria-label="Permalink to “5. nice”">​</a></h3><p>通过nice命令的帮助，用户可以设置和改变进程的优先级。提高一个进程的优先级，内核会分配更多CPU时间片给这个进程。默认情况下，进程以0的优先级启动。进程优先级可以通过top命令显示的NI（nice value）列查看。</p><p>进程优先级值的范围从-20到19。值越低，优先级越高。</p><pre><code>nice &lt;优先值&gt; &lt;进程名&gt; - 通过给定的优先值启动一个程序
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/nice-cmd.png" alt="nice command"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/top-nice.png" alt="changed nice value of &#39;top&#39;"></p><p>上述命令例子中，可以看到‘top’命令获得了-3的优先值。</p><h3 id="_6-renice" tabindex="-1">6. renice <a class="header-anchor" href="#_6-renice" aria-label="Permalink to “6. renice”">​</a></h3><p>renice命令类似nice命令。使用这个命令可以改变正在运行的进程优先值。注意，用户只能改变属于他们自己的进程的优先值。</p><pre><code>renice -n -p - 改变指定进程的优先值
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/renice2.png" alt="renice command"></p><p>初始优先值为0的3806号进程优先值已经变成了4.</p><pre><code>renice -u -g - 通过指定用户和组来改变进程优先值
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/renice1.png" alt="output of renice for a user group"></p><p>上述例子中，用户为‘mint’的所有进程优先值变为‘-3’。</p><h3 id="_7-kill" tabindex="-1">7. kill <a class="header-anchor" href="#_7-kill" aria-label="Permalink to “7. kill”">​</a></h3><p>这个命令用于发送信号来结束进程。如果一个进程没有响应杀死命令，这也许就需要强制杀死，使用-9参数来执行。注意，使用强制杀死的时候一定要小心，因为进程没有时机清理现场，也许写入文件没有完成。如果我们不知道进程PID或者打算用名字杀死进程时候，killall就能派上用场。</p><pre><code>kill &lt;pid&gt;

kill -9 &lt;pid&gt;

killall -9 - 杀死所有拥有同样名字的进程
</code></pre><p>如果你使用kill，你需要知道进程ID号。pkill是类似的命令，但使用模式匹配，如进程名，进程拥有者等。</p><pre><code>pkill &lt;进程名&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/kill-initiated.png" alt="kill initiated"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/kill.png" alt="kill"></p><h3 id="_8-ulimit" tabindex="-1">8. ulimit <a class="header-anchor" href="#_8-ulimit" aria-label="Permalink to “8. ulimit”">​</a></h3><p>该命令用于控制系统资源在shell和进程上的分配量。对于系统管理员是最有用的，可以管理重度使用和存在性能问题的系统。限制资源大小可以确保重要进程持续运行，其他进程不会占用过多资源。</p><pre><code>ulimit -a - 显示当前用户关联的资源限制
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/ulimit-a.png" alt="ulimit -a"></p><pre><code>-f - 最大文件尺寸大小

-v - 最大虚拟内存大小（KB）

-n - 增加最大文件描述符数量

-H : 改变和报告硬限制

-S : 改变和报告软限制
</code></pre><p>浏览ulimit man页面获取更多选项。</p><h3 id="_9-w" tabindex="-1">9. w <a class="header-anchor" href="#_9-w" aria-label="Permalink to “9. w”">​</a></h3><p>w 提供当前登录的用户及其正在执行的进程的信息。显示信息头包含信息，如当前时间、系统运行时长、登录用户总数、过去的1，5，15分钟内的负载均衡数。</p><p>基于这些用户信息，用户在终止不属于他们的进程时要小心。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/w.png" alt="&#39;w&#39; command"></p><p><strong>who</strong>是类似命令，提供当前登录用户列表、系统启动时间、运行级别等。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/who.png" alt="&#39;who&#39; command"></p><p><strong>whoami</strong> 命令输出当前用户ID</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/whoami.png" alt="&#39;whoami&#39; command"></p><h3 id="_10-pgrep" tabindex="-1">10. pgrep <a class="header-anchor" href="#_10-pgrep" aria-label="Permalink to “10. pgrep”">​</a></h3><p>pgrep的意思是&quot;进程号全局正则匹配输出&quot;。该命令扫描当前运行进程，然后按照命令匹配条件列出匹配结果到标准输出。对于通过名字检索进程号是很有用。</p><pre><code>pgrep -u mint sh
</code></pre><p>这个命令将会显示用户为‘mint’和进程名为‘sh’的进程ID。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/pgrep.png" alt="output of pgrep"></p><h3 id="_11-fg-bg" tabindex="-1">11. fg , bg <a class="header-anchor" href="#_11-fg-bg" aria-label="Permalink to “11. fg , bg”">​</a></h3><p>有时，命令需要很长的时间才能执行完成。对于这种情况，我们使用‘bg’命令可以将任务放在后台执行，而用‘fg’可以调到前台来使用。</p><p>我们可以通过‘&amp;’在后台启动一个程序:</p><pre><code>find . -name *iso &gt; /tmp/res.txt &amp;
</code></pre><p>一个正在运行的程序也可以通过“CTRL+Z”和“bg”命令组合放到后台运行。</p><pre><code>find . -name *iso &gt; /tmp/res.txt &amp;     -  启动一个程序

ctrl+z      -   挂起当前执行程序

bg   -  将程序放到后台运行
</code></pre><p>我们可以使用‘jobs’命令列出所有后台进程。</p><pre><code>jobs
</code></pre><p>使用‘fg’命令可以将后台程序调到前台执行。</p><pre><code>fg %进程id
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/fg-bg-jobs.png" alt="output of fg, bg and jobscommands"></p><h3 id="_12-ipcs" tabindex="-1">12. ipcs <a class="header-anchor" href="#_12-ipcs" aria-label="Permalink to “12. ipcs”">​</a></h3><p>ipcs命令报告进程间通信设施状态。（共享内存，信号量和消息队列）</p><p>用-p参数联合-m、-s或-q使用，可以获得相关的进程间通信的进程ID。</p><pre><code>ipcs -p -m
</code></pre><p>下面屏幕截图列出了最近访问了共享内存段的进程的创建者的ID和进程ID。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ipcs.png" alt="ipcs command"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>总之 ，这些命令可以帮助管理员修复问题和改善性能。同样作为一名普通用户也需要解决进程出现的问题。所以，熟悉如此繁多的命令，从能有效管理进程是行之有效。</p><hr>`,80)),i("p",null,[e[1]||(e[1]=p("via: ",-1)),n(t,{href:"http://linoxide.com/linux-command/process-management-commands-linux/"},{default:o(()=>[...e[0]||(e[0]=[p("http://linoxide.com/linux-command/process-management-commands-linux/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=p("作者：",-1)),n(t,{href:"http://linoxide.com/author/bnpoornima/"},{default:o(()=>[...e[2]||(e[2]=[p("B N Poornima",-1)])]),_:1}),e[6]||(e[6]=p(" 译者：",-1)),n(t,{href:"http://vicyu.net"},{default:o(()=>[...e[3]||(e[3]=[p("VicYu/Vic020",-1)])]),_:1}),e[7]||(e[7]=p(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[p("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=p("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[p("LCTT",-1)])]),_:1}),e[11]||(e[11]=p(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[p("Linux中国",-1)])]),_:1}),e[12]||(e[12]=p(" 荣誉推出",-1))])])}const w=a(c,[["render",m]]);export{P as __pageData,w as default};
